{
  "title": "Adaptive Learning Path",
  "subtitle": "Your lessons aren't fixed. They change based on how you actually speak.",
  "bullets": [
    {
      "icon": "🎧",
      "title": "Every session, AI listens",
      "description": "Every session, AI tracks your accuracy, fluency, and response speed."
    },
    {
      "icon": "🔀",
      "title": "Path adjusts automatically",
      "description": "Doing well → harder lessons. Struggling → targeted drills first. Content depends on how you do today."
    },
    {
      "icon": "📊",
      "title": "Always at your edge",
      "description": "Not too easy, not too hard. The AI finds your sweet spot every session."
    }
  ],
  "cta": "Got it — let's go 🚀"
}

{
  "title": "Welcome back 👋",
